ST.xhtml:p:
R_Trigger(CLK := g_bBoendeAvoidOpen);

IF R_Trigger.Q THEN
  g_bBoendeAvoidOpen := FALSE;
  g_bBoendeAvoidDone := FALSE;
  nAvoidState := 100;
END_IF;

IF Axis_Z.NCTOPLC.HOMINGSTATE AND g_bZAxisZero AND Axis_Z.NCTOPLC.ACTPOS >= g_fLiftCoord - 0.1 THEN
  g_bZAvoidStatus := TRUE;
ELSE
  g_bZAvoidStatus := FALSE;
END_IF;

CASE nAvoidState OF
  0:
    nAvoidState := 0;
  1:
    IF g_bZAvoidStatus THEN
      nAvoidState := 0;
      g_bBoendeAvoidDone := TRUE;
    ELSE
      nAvoidState := 100;
    END_IF;
  100:
    g_fZAbsPosition := g_fLiftCoord;
    g_bZAbsExecute := TRUE;
    nAvoidState := 110;
  110:
    IF g_bZAbsDone THEN
      g_bZAbsExecute := FALSE;
      nAvoidState := 140;
    ELSIF g_bPlcPauseBuffer THEN
      g_bZAbsExecute := FALSE;
      nAvoidState := 120;
    END_IF;
  120:
    IF g_bPlcStartBuffer THEN
      IF Axis_Z.NCTOPLC.ACTPOS > g_fLiftCoord - 0.1 THEN
        nAvoidState := 140;
      ELSE
        nAvoidState := 100;
      END_IF;
    END_IF;
  140:
    IF g_bZAvoidStatus THEN
      g_bBoendeAvoidDone := TRUE;
    ELSE
      IF NOT g_bZAvoidStatus THEN
        g_bBoendeZWarn := TRUE;
      END_IF;
    END_IF;
    nAvoidState := 0;
END_CASE;

IF g_bPlcResetBuffer THEN
  nAvoidState := 0;
  g_bZAbsExecute := FALSE;
  g_bBoendeAvoidOpen := FALSE;
END_IF;
